# Helper procs (source this after link_design). Pure OpenROAD/OpenSTA Tcl.
# node <name>     : the timing object for a signal: its port if it is a primary I/O, else the pin driving that net
proc node {n} {
  set p [get_ports -quiet $n]
  if {[llength $p]} { return $p }
  return [get_pins -of_objects [get_nets $n] -filter "direction==output"]
}
# inst_names <cells> [comb]: sorted instance names, dropping the top-level instance; with "comb", also drop DFFs
proc inst_names {cells {mode all}} {
  set r {}
  foreach c $cells {
    set n [get_full_name $c]
    if {$n eq ""} continue
    if {$mode eq "comb" && [get_property $c ref_name] eq "DFF"} continue
    lappend r $n
  }
  return [lsort $r]
}
# gdepth <report-args>: max number of gates on paths matching the args (e.g. -to [node X], -through [get_pins g/Y]).
#   PI-start paths use arrival directly; register-start paths subtract the CLK->Q stage (1). -1 = no path.
proc gdepth {args} {
  set best -1
  foreach {from adj} [list [all_inputs] 0 [all_registers -clock_pins] 1] {
    if {[llength $from] == 0} continue
    if {[catch {set ps [find_timing_paths -unconstrained -from $from {*}$args -group_count 1]}]} continue
    foreach p $ps {
      set a [expr {int(round([get_property [lindex [get_property $p points] end] arrival])) - $adj}]
      if {$a > $best} { set best $a }
    }
  }
  return $best
}
# fanout_ports <obj>: names of primary outputs structurally reachable from obj (honours set_disable_timing)
proc fanout_ports {obj} {
  set r {}
  foreach e [get_fanout -from $obj -flat -endpoints_only -trace_arcs enabled] {
    set n [get_full_name $e]
    if {[llength [get_ports -quiet $n]]} { lappend r $n }
  }
  return $r
}
# cut_pairs <wire>: "pi->po" pairs that are connected but lose every path when <wire> is blocked
proc cut_pairs {w} {
  set drv [get_cells -of_objects [node $w]]
  set pairs {}
  foreach p [get_fanin -to [node $w] -flat -startpoints_only] {
    set pn [get_full_name $p]
    if {![llength [get_ports -quiet $pn]]} continue
    set before [fanout_ports $p]
    set_disable_timing $drv
    set after [fanout_ports $p]
    unset_disable_timing $drv
    foreach q $before { if {$q ne $w && $q ni $after} { lappend pairs "$pn->$q" } }
  }
  return $pairs
}
# artic_points <src> <dst>: gates whose removal disconnects src from dst (empty list + message if no path)
proc artic_points {src dst} {
  set d [get_full_name [node $dst]]
  if {[lsearch -exact [fanout_ports [node $src]] $dst] < 0 && [llength [get_ports -quiet $dst]]} { puts "no combinational path"; return {} }
  set A [inst_names [get_fanout -from [node $src] -flat -only_cells] comb]
  set B [inst_names [get_fanin -to [node $dst] -flat -only_cells] comb]
  set res {}
  foreach g $A {
    if {$g ni $B} continue
    set_disable_timing [get_cells $g]
    if {[lsearch -exact [fanout_ports [node $src]] $dst] < 0} { lappend res $g }
    unset_disable_timing [get_cells $g]
  }
  return $res
}
# const_loads <0|1> [cell-type-glob]: cells with an input pin tied to constant 0/1
#   (OpenROAD represents 1'b1 / 1'b0 as nets named one_ / zero_)
proc const_loads {val {type *}} {
  set net [expr {$val ? "one_" : "zero_"}]
  set r {}
  foreach p [get_pins -quiet -of_objects [get_nets -quiet $net] -filter "direction==input"] {
    set c [get_cells -of_objects $p]
    if {[string match $type [get_property $c ref_name]]} { lappend r [get_full_name $c] }
  }
  return [lsort -unique $r]
}
# putl <list>: print one item per line (very long single-line puts output can come out garbled in OpenROAD)
proc putl {l} { foreach x $l { puts $x } }

